      strictEqual(isValidPort(i), true)
    }
  })
  test('returns true for port in range of 0 to 65535 as string', () => {
    for (let i = 0; i < 65536; i++) {
      strictEqual(isValidPort(i.toString()), true)
    }
  })
})

